import{_ as a,o as e,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Python 工程与数据","description":"","frontmatter":{"title":"Python 工程与数据"},"headers":[],"relativePath":"py-agent/foundations/python-engineering-data/index.md","filePath":"py-agent/foundations/python-engineering-data/index.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/python-engineering-data/index.md"};function d(r,t,l,h,p,s){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="python-工程与数据" tabindex="-1">Python 工程与数据 <a class="header-anchor" href="#python-工程与数据" aria-label="Permalink to &quot;Python 工程与数据&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>前两个 Python 分组解释语言规则和代码抽象，本分组继续解决工程边界：怎样让项目在明确环境中重复运行，怎样把配置和密钥送入应用，怎样用静态类型描述代码关系，怎样把不可信外部数据转换成已验证对象，以及怎样用测试证明这些契约没有被破坏。</p><h2 id="本分组的作用" tabindex="-1">本分组的作用 <a class="header-anchor" href="#本分组的作用" aria-label="Permalink to &quot;本分组的作用&quot;">​</a></h2><p>Agent 应用通常依赖模型 SDK、HTTP 客户端、环境变量、JSON 响应和第三方数据模型。代码“在当前电脑能运行”并不等于项目可复现；类型标注“看起来正确”也不等于外部输入已经校验。本分组把运行环境、静态关系、运行时数据和行为验证分成不同层次，避免用单个工具代替所有边界。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>完成本分组后，你应当能够：</p><ol><li>建立包含包、测试、虚拟环境和依赖声明的可重复运行项目。</li><li>按明确优先级读取配置，并在启动阶段转换和验证环境变量。</li><li>使用类型标注描述函数、容器、联合类型和可空值，并在分支中收窄类型。</li><li>使用 <code>Protocol</code> 让调用方依赖行为契约，而不是具体实现类。</li><li>解释 JSON 与 Python 类型的映射、往返损失和严格解析边界。</li><li>使用 Pydantic 2.x 把不可信输入转换为经过验证的模型，并输出错误和 JSON Schema。</li><li>使用 pytest 验证纯函数、异常、边界对象、Fake 实现和共享接口契约。</li></ol><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><ol><li><a href="/py-agent/foundations/python-engineering-data/project-environment-dependencies">项目、环境与依赖</a></li><li><a href="/py-agent/foundations/python-engineering-data/configuration-secrets">配置与密钥</a></li><li><a href="/py-agent/foundations/python-engineering-data/type-annotations-narrowing">类型标注与收窄</a></li><li><a href="/py-agent/foundations/python-engineering-data/protocol-interface-boundaries">Protocol 与接口边界</a></li><li><a href="/py-agent/foundations/python-engineering-data/json-data-boundaries">JSON 数据边界</a></li><li><a href="/py-agent/foundations/python-engineering-data/pydantic-data-contracts">Pydantic 数据契约</a></li><li><a href="/py-agent/foundations/python-engineering-data/pytest-contract-testing">pytest 与契约测试</a></li></ol><p>前两篇先固定运行环境和应用输入；类型与 Protocol 建立代码内部的静态契约；JSON 与 Pydantic 建立外部数据边界；pytest 最后验证这些行为。初学者建议按顺序阅读，因为测试文章会复用依赖注入、类型接口和数据校验概念。</p><h2 id="四层边界" tabindex="-1">四层边界 <a class="header-anchor" href="#四层边界" aria-label="Permalink to &quot;四层边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th><th>不负责什么</th></tr></thead><tbody><tr><td>环境与依赖</td><td>使用哪个解释器和依赖版本</td><td>业务数据是否合法</td></tr><tr><td>类型与 Protocol</td><td>静态分析时值和接口是否兼容</td><td>运行时拒绝不可信输入</td></tr><tr><td>JSON 与 Pydantic</td><td>外部文本如何解析、转换和校验</td><td>证明全部业务行为正确</td></tr><tr><td>pytest</td><td>给定输入下行为是否满足契约</td><td>真实模型输出质量评测</td></tr></tbody></table><h2 id="内容边界" tabindex="-1">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><p>本分组不展开公共包发布、容器、CI/CD、云密钥平台、复杂泛型、ORM、HTTP 调用和真实模型评测。协程与 HTTP 生命周期属于下一分组；模型请求、结构化输出和业务结果处理属于“模型应用基础”。</p><p>示例以 Python 3.12、Pydantic 2.x 和 pytest 8/9 的稳定核心 API 为基线。具体包解析器和锁文件格式可能因项目工具不同而变化，文章会明确区分通用原则与工具专属命令。</p>',16)])])}const g=a(i,[["render",d]]);export{y as __pageData,g as default};
